import os,json,subprocess
from pathlib import Path
unit=Path("/etc/systemd/system/pink-vpn.service")
out={"unit":{},"unit_env":{},"python_configs":{},"active_pids":{}}
if unit.is_file():
 b=unit.read_text(errors="replace")
 out["unit"]["safe_lines"]=[l for l in b.splitlines() if l.startswith(("WorkingDirectory=","ExecStart=","EnvironmentFile=","Environment=","User=","StateDirectory=","ReadWritePaths=","RuntimeDirectory="))]
 out["unit"]["literal_old_refs"]=b.count("/var/lib/pink-vpn")
 out["unit"]["verify"]=subprocess.run(["systemd-analyze","verify",str(unit)],capture_output=True,timeout=10).returncode==0
 import re
 refs=re.findall(r"^EnvironmentFile=-?([^\s]+)",b,re.M)
 for f in refs:
  p=Path(f)
  if p.is_file() and not p.is_symlink():
   data=p.read_bytes()
   out["unit_env"][f]={"old_state_path_occurrences":data.count(b"/var/lib/pink-vpn"),"new_state_path_occurrences":data.count(b"/srv/projects/pink-iptv/vpn/data"),"keys_with_old_path":[line.split(b"=",1)[0].decode(errors="replace")[:70] for line in data.splitlines() if b"/var/lib/pink-vpn" in line][:12]}
service=subprocess.run(["systemctl","show","pink-vpn","--property=MainPID,ActiveState"],capture_output=True,text=True,timeout=8)
out["active_pids"]={x.split("=",1)[0]:x.split("=",1)[1] for x in service.stdout.splitlines() if "=" in x}
for base in (Path("/srv/projects/pink-iptv/backend"),Path("/srv/projects/pink-iptv/infra"),Path("/srv/projects/pink-iptv/shared")):
 hits=[]
 if base.is_dir():
  for cur,dirs,files in os.walk(base,followlinks=False):
   if len(Path(cur).relative_to(base).parts)>4:dirs[:]=[];continue
   dirs[:]=[x for x in dirs if x not in ("node_modules",".venv",".git","__pycache__",".mypy_cache","build","dist","archive","data","private")]
   for n in files:
    p=Path(cur)/n
    try:
     if p.is_symlink() or not p.is_file() or p.stat().st_size>90000:continue
     b=p.read_bytes()
     if b"/var/lib/pink-vpn" in b:hits.append({"path":str(p.relative_to(base)),"count":b.count(b"/var/lib/pink-vpn")})
    except OSError:pass
 out["python_configs"][str(base)]=hits[:20]
print(json.dumps(out,sort_keys=True))
